(() => {
  'use strict';
  const lessons = [
    {id:'help-route',title:'Как попросить о помощи и быть услышанным',topic:'Маршрут помощи',ages:['6–10 лет','11–14 лет','15–18 лет'],goal:'Участники узнают, как обратиться к безопасному взрослому, сообщить факты и продолжать искать помощь, если первый взрослый не отреагировал.',materials:'Карточки ситуаций, лист бумаги, доска.',steps:[['Начало и безопасность',5,'Скажи: мы обсуждаем вымышленные примеры, не называем имён и не просим рассказывать личные истории. Можно пропустить любой ответ.'],['Что значит обратиться за помощью',7,'Объясни: просить помощи — нормальный и ответственный шаг. Важно сообщить взрослому, что произошло, где и какая поддержка нужна.'],['Разбор ситуации',10,'Прочитайте карточку №1. Предложите несколько безопасных вариантов действий. Не оценивайте ребёнка, который растерялся или не смог сразу обратиться.'],['Репетиция фразы',10,'В малых группах потренируйте нейтральную фразу: «Мне нужно сообщить о ситуации. Происходит ___. Я беспокоюсь за безопасность. Помогите, пожалуйста, разобраться».'],['Если не услышали',5,'Обсуди следующий шаг: обратиться к другому ответственному взрослому, классному руководителю, школьному психологу, администрации или родителю.'],['Завершение',3,'Попроси назвать один возможный канал помощи. Не требуй публичных обещаний.']],cards:[['Ситуация 1. Нужна помощь','Ученик замечает, что одноклассника регулярно унижают в общем чате. Он хочет сообщить взрослому, но боится, что станет хуже.','Какие факты можно сообщить? Кому? Как не распространять унизительные сообщения дальше?'],['Ситуация 2. Не услышали','Ученик рассказал взрослому о происходящем, но услышал: «Не обращай внимания». Ситуация продолжается.','К кому ещё можно обратиться? Как повторно сообщить о продолжающейся опасности?'],['Ситуация 3. Срочная опасность','Во время перемены возникла угроза физической расправы. Рядом есть дежурный педагог.','Как быстро привлечь взрослого? Почему нельзя вмешиваться в опасную драку в одиночку?']],exercise:'Составьте короткое обращение по схеме: что произошло — где/когда — кому может быть нужна защита — какая помощь нужна сейчас.',teacher:'Если ребёнок сообщает о реальном эпизоде, поблагодари за доверие, уточни непосредственную безопасность и действуй по школьному алгоритму. Не обещай абсолютную тайну и не устраивай публичный разбор.',quiz:[["Что лучше сообщить взрослому?",["Только слухи от других","Что произошло, где и какая помощь нужна","Кто, по мнению класса, виноват"],1,"Факты помогают взрослому оценить ситуацию и организовать поддержку."],["Если первый взрослый не отреагировал, что делать?",["Перестать обращаться за помощью","Ответить угрозами","Обратиться к другому ответственному взрослому"],2,"Если ситуация продолжается, важно сообщить другому ответственному взрослому."],["Что делать при непосредственной угрозе?",["Самостоятельно вмешаться в опасную ситуацию","Срочно привлечь взрослого и действовать по школьному порядку","Снять видео и выложить его"],1,"При угрозе безопасность важнее самостоятельного вмешательства или публикаций."]]},
    {id:'witness',title:'Свидетель: как помочь и не усилить травлю',topic:'Поддержка свидетеля',ages:['6–10 лет','11–14 лет','15–18 лет'],goal:'Участники различают безопасные способы поддержки и действия, которые могут усилить вред.',materials:'Карточки ситуаций, листы «безопасно / рискованно».',steps:[['Правила разговора',5,'Не разыгрываем травлю и не назначаем роли «обидчика» и «жертвы». Рассматриваем только вымышленные ситуации.'],['Кто такой свидетель',6,'Свидетель — тот, кто видит или узнаёт о происходящем. Он не обязан рисковать собой, чтобы помочь.'],['Сортировка действий',10,'Разложи варианты: поддержать человека, позвать взрослого, переслать видео, присоединиться к насмешкам, сохранить доказательство безопасным способом и передать взрослому. Обсудите последствия.'],['Карточка ситуации',9,'Разберите карточку №1 или №2. Найдите безопасное действие, которое реально выполнить.'],['Фразы поддержки',7,'Потренируйте фразы: «Я вижу, что это неприятно. Пойдём вместе к взрослому»; «Я не буду это пересылать».'],['Итог',3,'Подчеркни: ответственность за остановку травли лежит на взрослых и школе, а не на ребёнке-свидетеле.']],cards:[['Ситуация 1. Чат','В общем чате публикуют унизительный мем про ученика. Несколько человек ставят смеющиеся реакции.','Почему пересылка усиливает вред? Что можно сделать вместо этого?'],['Ситуация 2. Перемена','Несколько учеников окружили одноклассника и не дают ему уйти. Ты это видишь из коридора.','Как привлечь дежурного взрослого? Почему не нужно физически вмешиваться одному?'],['Ситуация 3. После урока','Одноклассник сидит один и выглядит расстроенным после повторяющихся насмешек.','Как предложить поддержку без давления? Как помочь обратиться к взрослому?']],exercise:'В парах составьте два коротких сценария: поддержка пострадавшего без давления и сообщение взрослому без распространения слухов.',teacher:'Не возлагай на свидетелей обязанность самостоятельно прекращать опасное поведение. Не поощряй публичные конфронтации, угрозы или публикацию ответных материалов.',quiz:[["Что может сделать свидетель безопасно?",["Позвать взрослого и предложить поддержку","Устроить публичную конфронтацию","Переслать унизительный мем"],0,"Свидетель может поддержать человека и привлечь взрослого, не подвергая себя опасности."],["Нужно ли свидетелю самостоятельно остановить травлю?",["Да, любой ценой","Нет, ответственность за безопасность несут взрослые","Только если его снимают на видео"],1,"Ребёнок не обязан рисковать собой; задача свидетеля — не усиливать вред и обратиться за помощью."],["Почему не стоит пересылать унизительный контент?",["Он может усилить распространение и вред","Потому что сообщения нельзя читать","Потому что это всегда шутка"],0,"Пересылка увеличивает аудиторию и может повторно причинить вред."]]},
    {id:'digital',title:'Цифровая безопасность и травля в сети',topic:'Цифровая безопасность',ages:['6–10 лет','11–14 лет','15–18 лет'],goal:'Участники понимают, что онлайн-унижение тоже причиняет реальный вред, и знают базовые шаги защиты и обращения за помощью.',materials:'Карточки вымышленных онлайн-ситуаций, бумага.',steps:[['Безопасные правила',5,'Не показываем личные переписки и аккаунты класса. Не называем реальные имена и не воспроизводим оскорбительный контент.'],['Онлайн и офлайн',7,'Обсуди: сообщение, изображение или исключение из чата может причинять вред и после окончания уроков.'],['Что делать сначала',8,'Остановить пересылку, не отвечать угрозами, обратиться к взрослому. Если безопасно, сохранить ссылку/скриншот для передачи ответственному взрослому, не публикуя его.'],['Разбор карточек',10,'Разберите вымышленные ситуации и выберите безопасную последовательность действий.'],['Настройки и поддержка',7,'Обсуди блокировку и жалобу на платформе как дополнительные меры, а не замену помощи взрослого.'],['Завершение',3,'Каждый может назвать один способ прекратить распространение вреда и один канал помощи.']],cards:[['Ситуация 1. Пересылка','В чате распространяют изменённую фотографию ученика с унизительной подписью.','Что нельзя делать с этим материалом? Кому передать информацию?'],['Ситуация 2. Угрозы','В личных сообщениях подростку пишут угрозы и требуют прислать личные фотографии.','Почему важно немедленно обратиться к доверенному взрослому? Как сохранить сообщения, не пересылая их другим?'],['Ситуация 3. Исключение','Участников класса договорились исключить одного ученика из общего чата и высмеивать его в другом.','Как сообщить о ситуации взрослому? Почему это не «просто интернет»?']],exercise:'Составьте памятку из четырёх шагов: остановить распространение — не отвечать угрозами — сохранить нужные сведения безопасным способом — обратиться к взрослому.',teacher:'При угрозах, шантаже, сексуализированном вымогательстве, публикации интимных изображений или непосредственной опасности действуй незамедлительно по школьному алгоритму и требованиям закона. Не проси ребёнка пересылать интимные материалы.',quiz:[["Что сделать с оскорбительными сообщениями?",["Ответить ещё более обидно","Не распространять их, сохранить доказательства безопасно и сообщить взрослому","Удалить всё и никому не говорить"],1,"Важно не усиливать распространение, сохранить необходимые сведения и привлечь взрослого."],["Кому нужно сообщить об угрозах или шантаже?",["Только друзьям","Никому, чтобы не стало хуже","Надёжному взрослому незамедлительно"],2,"Угрозы и шантаж требуют быстрой помощи ответственного взрослого."],["Можно ли публиковать реальные переписки одноклассников на уроке?",["Нет, используем только вымышленные примеры","Да, если большинство согласны","Да, если скрыть одно имя"],0,"Личные переписки и узнаваемые детали нельзя выносить на публичное обсуждение."]]},
    {id:'safe-climate',title:'Класс, в котором безопасно каждому',topic:'Безопасная среда',ages:['6–10 лет','11–14 лет','15–18 лет'],goal:'Класс формулирует конкретные правила уважительного общения и понятный способ реагирования на нарушение безопасности.',materials:'Стикеры или листы, доска.',steps:[['Старт',5,'Договорись: обсуждаем правила, а не конкретных учеников. Не используем личные истории и не называем имён.'],['Что такое безопасная среда',7,'Собери признаки: можно учиться без унижения, отказ уважают, взрослые реагируют, помощь доступна.'],['Разбор примеров',8,'Прочитайте карточки №1–3. Отделите несогласие и разовый спор от повторяющегося унижения и угроз. Любая угроза требует внимания взрослых.'],['Создание правил',10,'Сформулируйте 4–6 наблюдаемых правил: не унижать; не распространять чужие фото; уважать отказ; звать взрослого при угрозе; не поддерживать травлю реакциями и пересылками.'],['Что делают взрослые',7,'Назови школьные роли и реальные каналы обращения, которые подтверждены самой школой. Не придумывай контакты.'],['Итог',3,'Выберите одно правило, которое школа может поддерживать ежедневно.']],cards:[['Ситуация 1. Шутка','Ученик просит прекратить шутки о своей внешности, но они продолжаются.','Почему просьбу остановиться нужно уважать? Что может сделать взрослый?'],['Ситуация 2. Разногласие','Два ученика не согласны, как выполнять групповое задание. Они спорят, но не унижают друг друга.','Как договориться? Чем этот спор отличается от травли?'],['Ситуация 3. Повторяющееся исключение','Одного ученика систематически не берут в команды и публично высмеивают.','Какие признаки показывают, что нужна помощь взрослых? Как обеспечить безопасность?']],exercise:'Создайте короткий «план безопасного класса»: правило, как его заметить в повседневности, и что делает взрослый, если правило нарушено.',teacher:'Не проводи голосование о виновности и не организуй примирение сторон, если травля продолжается или есть неравенство сил. Сначала безопасность, индивидуальная оценка ситуации и действия взрослых.',quiz:[["Какое правило помогает создать безопасный класс?",["Можно продолжать шутку, если смешно большинству","Уважать просьбу прекратить неприятные слова","Не обращаться к взрослым"],1,"Если человеку неприятно, просьбу остановиться нужно уважать."],["Чем обычное разногласие отличается от травли?",["Разногласие всегда является травлей","В травле могут быть повторяемость и неравенство сил","Никак не отличается"],1,"При оценке учитывают повторяемость, дисбаланс сил и причиняемый вред; угрозы требуют реакции взрослых и в единичном случае."],["Кто отвечает за безопасность в школе?",["Только сами ученики","Только свидетели","Взрослые и школьная система реагирования"],2,"Дети участвуют в уважительном общении, но ответственность за защиту и реагирование лежит на взрослых."]]},
    {id:'recognize-bullying',title:'Как распознать травлю и отличить её от обычного конфликта',topic:'Конфликт и травля',ages:['6–10 лет','11–14 лет','15–18 лет'],goal:'Участники учатся замечать признаки повторяющегося давления, отличать его от обычного разногласия и понимать, когда необходимо вмешательство взрослых.',materials:'Карточки вымышленных ситуаций, доска или листы бумаги, карточки «повторяется / не повторяется», «равные силы / неравные силы».',intro:'Конфликт — это разногласие, в котором стороны могут выражать разные мнения. Травля — повторяющееся причинение вреда при неравенстве сил или возможностей защититься. При этом единичная угроза или насилие тоже требуют внимания взрослых.',steps:[['Безопасное начало',5,'Договоритесь: обсуждаем только вымышленные истории, не называем имён и не разбираем реальные случаи класса. Каждый может не отвечать на вопрос.'],['Конфликт и травля',8,'Объясни разницу на нейтральных примерах. Для оценки ситуации задаём вопросы: повторяется ли поведение, есть ли неравенство сил, причиняется ли вред? Это ориентиры для внимательного взрослого, а не тест для постановки диагноза.'],['Разбор признаков',8,'Предложи три вымышленных примера: спор о правилах игры; повторяющиеся насмешки группой над одним учеником; единичная угроза после урока. Обсудите, что известно и почему во всех случаях угрозы или насилия нужен взрослый.'],['Работа с ситуациями',12,'В малых группах разберите карточки. Не ищите виноватого и не голосуйте. Составьте список фактов, которые важно передать взрослому, и мер, которые помогут обеспечить безопасность.'],['Алгоритм обращения',7,'Если ситуация тревожит: отойти в безопасное место, обратиться к надёжному взрослому, кратко сообщить факты и сказать, какая помощь нужна. Если первый взрослый не помог, обратиться к другому.'],['Итог',5,'Повторите: не нужно самостоятельно расследовать травлю или противостоять группе. Взрослые должны оценить ситуацию и обеспечить безопасность.']],cards:[['Ситуация 1. Разногласие','Два ученика спорят, какую тему выбрать для общего проекта. Оба могут высказать мнение, угроз и унижений нет.','Что поможет договориться? Какие признаки показывают, что это разногласие?'],['Ситуация 2. Повторяющиеся насмешки','Несколько учеников каждую неделю высмеивают одного одноклассника и не прекращают после просьб.','Что указывает на повторяющееся давление? Почему важно подключить взрослых?'],['Ситуация 3. Единичная угроза','После урока ученик говорит другому: «Я тебя ударю», и преграждает ему путь. Раньше такого не было.','Почему даже единичная угроза требует реакции взрослого? Как безопасно позвать помощь?']],exercise:'Разберите вымышленную ситуацию по трём вопросам: повторяется ли поведение; есть ли неравенство сил; причиняется ли вред. Затем запишите, к какому взрослому можно обратиться и какие факты сообщить.',teacher:'Не используйте три вопроса как автоматический диагностический тест. Не просите детей определять, кто «жертва» или «агрессор». При угрозе, насилии или сообщении ребёнка уточните непосредственную безопасность и действуйте по школьному порядку. Не организуйте примирение при продолжающемся давлении.',ageNotes:'6–10 лет: короткие истории и карточки с простыми признаками. 11–14 лет: разбор группового давления и исключения. 15–18 лет: анализ повторяемости, дисбаланса сил, цифрового контекста и школьных процедур.',quiz:[['Что может указывать на травлю?',['Любое несогласие','Повторяющееся причинение вреда при неравенстве сил','Разовая ошибка в совместном задании'],1,'Для травли характерны повторяемость и дисбаланс сил; ситуацию оценивают взрослые с учётом контекста.'],['Если угроза прозвучала один раз, можно ничего не делать?',['Да, единичные угрозы не важны','Нет, угрозы и насилие требуют внимания взрослых','Нужно сначала провести голосование класса'],1,'Даже единичная угроза или насилие требуют реакции взрослых.'],['Что должен сделать ученик, заметивший возможную травлю?',['Самостоятельно расследовать и наказать участников','Публично назвать виновных','Обратиться к надёжному взрослому и сообщить факты'],2,'Ребёнок не должен самостоятельно расследовать или останавливать опасную ситуацию.']]},
    {id:'group-pressure',title:'Почему люди присоединяются к травле и как этому противостоять',topic:'Групповое давление и ответственность',ages:['6–10 лет','11–14 лет','15–18 лет'],goal:'Участники понимают, как групповое давление влияет на поведение, различают объяснение и оправдание агрессии и находят безопасные способы не поддерживать вред.',materials:'Карточки вымышленных ситуаций, листы «поддерживает безопасность / усиливает вред».',intro:'Люди могут присоединяться к насмешкам из желания быть принятыми, страха стать следующей мишенью, стремления к популярности или потому, что повторяют поведение группы. Эти причины помогают понять ситуацию, но не оправдывают причинение вреда.',steps:[['Начало и правила',5,'Обозначь, что рассматриваются только вымышленные примеры. Не назначайте одноклассников на роли и не вспоминайте реальные случаи класса.'],['Почему группа влияет',8,'Обсудите желание быть принятым, страх выделиться, подражание, стремление получить одобрение и привычку считать унижение шуткой. Подчеркни: объяснить причину — не значит оправдать поступок.'],['Роли в ситуации',7,'На примере вымышленной истории выделите действия инициатора, присоединившихся, наблюдателей и тех, кто поддерживает безопасность. Это роли в конкретной ситуации, а не постоянные характеристики людей.'],['Сортировка поступков',10,'Распределите варианты: поставить смеющуюся реакцию; переслать мем; не участвовать; предложить человеку уйти вместе; сообщить взрослому; спокойно сказать «это не смешно» только если безопасно. Обсудите последствия.'],['Безопасный выбор',7,'Потренируйте короткие фразы отказа от участия: «Я не буду это пересылать»; «Давайте остановимся»; «Пойдём позовём взрослого». Подчеркни, что не нужно вступать в спор с группой, если это опасно.'],['Итог',3,'Ответственность за прекращение травли лежит на взрослых и школе. Любой участник может не усиливать вред и обратиться за помощью.']],cards:[['Ситуация 1. Чтобы быть своим','В чате несколько учеников высмеивают одноклассника. Новый участник ставит смеющуюся реакцию, потому что боится оказаться следующим.','Что могло повлиять на его решение? Как не поддерживать унижение и не подвергать себя опасности?'],['Ситуация 2. «Все так делают»','Компания регулярно исключает одного ученика из общих игр. Участники говорят, что это просто традиция.','Почему привычка группы не делает поступок безопасным? Что может сделать взрослый?'],['Ситуация 3. Поддержка','Ученик замечает, что одноклассник остался один после насмешек. Он хочет помочь, но не уверен, что сказать.','Какая фраза поддержки не обвиняет и не давит? Как предложить обратиться к взрослому?']],exercise:'Составьте два безопасных ответа на групповое давление: один — отказ участвовать в унижении, второй — обращение к взрослому. Не предлагайте детям вступать в опасную конфронтацию.',teacher:'Не называйте свидетелей трусами и не возлагайте на них ответственность остановить травлю. Не делите детей на постоянные категории. Если ребёнок сообщает о реальном эпизоде, поблагодарите за доверие и действуйте по школьному порядку.',ageNotes:'6–10 лет: сказочные или бытовые истории о выборе группы. 11–14 лет: влияние реакций, чатов и популярности. 15–18 лет: групповая динамика, конформность и ответственность за распространение контента.',quiz:[['Почему человек может присоединиться к насмешкам?',['Только потому, что он всегда жестокий','Из-за давления группы, страха или желания одобрения','Потому что насмешки никогда не причиняют вред'],1,'Групповое давление может влиять на поведение, но не оправдывает причинение вреда.'],['Что означает «объяснить, но не оправдать»?',['Понять возможную причину и всё равно считать вредное поведение недопустимым','Согласиться с любым поступком','Переложить ответственность на того, кого обижают'],0,'Причины помогают понять динамику, но ответственность за поступки сохраняется.'],['Как безопаснее всего отказаться от участия?',['Угрожать всей группе','Распространить ответный мем','Не пересылать контент и обратиться к взрослому'],2,'Не усиливать распространение и привлекать взрослого — безопасные способы не поддерживать вред.']]},
    {id:'support-classmate',title:'Как безопасно поддержать одноклассника',topic:'Поддержка и роль свидетеля',ages:['6–10 лет','11–14 лет','15–18 лет'],goal:'Участники осваивают безопасные способы проявить поддержку, выслушать без давления и помочь обратиться к взрослому.',materials:'Карточки вымышленных ситуаций, листы с фразами поддержки.',intro:'Поддержка — это не обязанность самостоятельно остановить травлю. Можно показать человеку, что он не один, выслушать без обвинений и помочь связаться со взрослым.',steps:[['Безопасное начало',5,'Не разыгрывайте травлю и не назначайте роли. Обсуждайте вымышленные истории; любой участник может пропустить упражнение.'],['Пять шагов поддержки',8,'Предложи схему: заметить; показать присутствие; выслушать; предложить помощь; вместе обратиться к взрослому. Человек сам выбирает, готов ли говорить, кроме ситуаций непосредственной опасности, когда взрослого нужно привлечь сразу.'],['Полезные и вредные фразы',8,'Сравните: «Я рядом, хочешь, пойдём к взрослому?» и «Сам виноват, не обращай внимания». Объясни, почему важно не обесценивать переживания и не обещать хранить опасную тайну.'],['Практика фраз',10,'В парах потренируйте спокойные фразы: «Хочешь, я побуду рядом?»; «Я могу пойти с тобой к педагогу»; «Тебе не нужно справляться одному». Не требуйте от партнёра личного рассказа.'],['Разбор ситуаций',7,'Разберите карточки: повторяющиеся насмешки; унизительный контент в чате; угроза со стороны старших. Для каждой ситуации определите, когда нужна немедленная помощь взрослого.'],['Завершение',2,'Подчеркни: не нужно рисковать собой, вступать в драку, вступать в конфронтацию с группой или добиваться признания. Взрослые отвечают за безопасность.']],cards:[['Ситуация 1. Повторяющиеся насмешки','Одноклассника регулярно высмеивают на переменах. После урока он сидит один и не хочет разговаривать.','Как показать, что ты рядом, не заставляя его рассказывать? Как предложить помощь взрослого?'],['Ситуация 2. Чат','В общем чате публикуют унизительные изображения ученика. Он просит никому не рассказывать, но сообщения продолжаются.','Как поддержать его и объяснить, что для защиты может понадобиться помощь взрослого?'],['Ситуация 3. Угроза','Старшие ученики угрожают младшему и не дают ему пройти.','Почему нельзя вмешиваться физически в одиночку? Как срочно привлечь взрослого?']],exercise:'Составьте короткий диалог поддержки из трёх реплик: показать присутствие, предложить выбор, предложить вместе обратиться к взрослому.',teacher:'Не заставляйте ребёнка раскрывать подробности и не обещайте абсолютную тайну. При угрозах или насилии немедленно привлекайте ответственных взрослых. Не организуйте прямую встречу с теми, кто оказывает давление.',ageNotes:'6–10 лет: простые фразы «я рядом» и «пойдём к учителю». 11–14 лет: поддержка в классе и цифровой среде. 15–18 лет: уважение автономии, конфиденциальность в допустимых пределах и школьные маршруты помощи.',quiz:[['Какой первый шаг поддержки подходит?',['Потребовать немедленно всё рассказать','Показать, что ты рядом, и предложить помощь без давления','Спросить, чем человек сам заслужил такое отношение'],1,'Поддержка начинается с уважительного присутствия и отсутствия обвинений.'],['Можно ли обещать никому не рассказывать об угрозах?',['Да, всегда','Нет, нельзя обещать абсолютную тайну, если нужна защита','Можно, если попросили друзья'],1,'При угрозе или насилии нужно подключить ответственных взрослых, спокойно объяснив это ребёнку.'],['Что делать, если есть непосредственная угроза?',['Срочно привлечь взрослого','Самостоятельно вступить в драку','Снять видео и выложить его'],0,'Безопасность важнее самостоятельной конфронтации или публикации.']]},
    {id:'cyberbullying-action',title:'Кибербуллинг: что делать, если травят в интернете',topic:'Цифровая безопасность',ages:['6–10 лет','11–14 лет','15–18 лет'],goal:'Участники распознают формы онлайн-травли и знают безопасный алгоритм защиты, сохранения необходимых сведений и обращения за помощью.',materials:'Карточки вымышленных онлайн-ситуаций, схема «остановись — сохрани — заблокируй/пожалуйся — сообщи взрослому».',intro:'Онлайн-унижение, угрозы, распространение личной информации и намеренное исключение из цифрового общения могут причинять реальный вред. Не нужно отвечать агрессией или пересылать вредный контент дальше.',steps:[['Правила цифровой безопасности',5,'Не открывайте личные переписки и реальные аккаунты класса. Не показывайте реальные скриншоты. Используйте только вымышленные ситуации.'],['Что может быть кибербуллингом',8,'Обсудите повторяющиеся оскорбления, унизительные мемы, распространение слухов и личных данных, угрозы, преследование и намеренное исключение. Не всякий неприятный спор является травлей, но угрозы и шантаж требуют быстрой реакции взрослых.'],['Безопасный алгоритм',10,'Не отвечать угрозами и не вступать в перепалку; не пересылать контент; сохранить необходимые доказательства безопасным способом, если это не подвергает риску; использовать блокировку и жалобу; сообщить надёжному взрослому.'],['Особые риски',7,'При угрозах, шантаже, вымогательстве, распространении интимных изображений или публикации адреса/телефона нужно немедленно сообщить взрослому. Не скачивать и не пересылать интимные материалы.'],['Разбор ситуаций',7,'В группах разберите вымышленные карточки и составьте безопасный план. Не просите участников показывать личные переписки.'],['Итог',3,'Повторите: не оставаться одному с угрозами, не распространять вредный контент и обращаться к взрослым.']],cards:[['Ситуация 1. Унижения в чате','В школьном чате несколько дней подряд публикуют оскорбления в адрес ученика.','Как не усилить распространение? Что можно сохранить и кому сообщить?'],['Ситуация 2. Шантаж','Неизвестный аккаунт угрожает распространить личные фотографии, если ученик не выполнит требование.','Почему важно немедленно обратиться к взрослому? Почему нельзя отправлять новые материалы или платить?'],['Ситуация 3. Исключение','Группу класса используют, чтобы постоянно исключать одного ученика и распространять о нём слухи.','Какие настройки или инструменты платформы могут помочь? Как подключить взрослого?']],exercise:'Соберите памятку из пяти шагов: не отвечать агрессией; не пересылать; безопасно сохранить необходимые сведения; заблокировать/пожаловаться; сообщить взрослому.',teacher:'Не просите детей демонстрировать личную переписку классу. При угрозах, шантаже, сексуализированном контенте или публикации персональных данных подключите ответственных взрослых незамедлительно и следуйте школьному и применимому правовому порядку.',ageNotes:'6–10 лет: правило «закрой экран и позови взрослого», без самостоятельной настройки сложных сервисов. 11–14 лет: блокировка, жалоба, приватность и безопасное сохранение сведений. 15–18 лет: цифровые следы, правовые риски распространения контента и маршруты срочной помощи.',quiz:[['Что делать в первую очередь при онлайн-унижении?',['Ответить ещё более оскорбительно','Не усиливать переписку и обратиться за поддержкой','Переслать сообщение всем знакомым'],1,'Ответная агрессия и пересылка могут усилить вред. Нужна поддержка взрослого.'],['Как поступить с доказательствами?',['Публиковать их в общем чате','Пересылать всем друзьям','Сохранить необходимые сведения безопасно и передать взрослому'],2,'Сведения сохраняют только настолько, насколько это безопасно, и передают ответственному взрослому.'],['Что делать при шантаже или угрозах интимными материалами?',['Немедленно сообщить надёжному взрослому, не пересылать материалы','Выполнить требования шантажиста','Самостоятельно договориться с ним'],0,'Шантаж и угрозы требуют немедленного подключения взрослого. Не пересылайте интимные материалы.']]},
    {id:'anger-regulation',title:'Как управлять гневом и остановить агрессивное поведение',topic:'Эмоции и саморегуляция',ages:['6–10 лет','11–14 лет','15–18 лет'],goal:'Участники различают эмоцию и поступок, замечают признаки нарастания гнева и осваивают безопасные способы паузы и выражения недовольства.',materials:'Карточки эмоций, листы бумаги, памятка «СТОП».',intro:'Злиться — нормально. Но эмоция не даёт права унижать, угрожать или причинять вред. Если ситуация опасна, ребёнку не нужно справляться самостоятельно: нужно отойти в безопасное место и привлечь взрослого.',steps:[['Безопасное начало',5,'Объясни, что любые эмоции допустимы, а вредные действия требуют остановки и ответственности. Не проси детей рассказывать о личных конфликтах.'],['Как тело сообщает о гневе',7,'Назовите возможные сигналы: напряжение, учащённое дыхание, сжатые кулаки, желание кричать. У разных людей сигналы могут отличаться.'],['Алгоритм СТОП',10,'С — Стоп: не действуй импульсивно. Т — Тихая пауза: отойди в безопасное место и выдохни. О — Определи чувство и потребность. П — Подбери безопасный поступок: сказать о границе, попросить паузу, обратиться к взрослому.'],['Безопасные фразы',8,'Потренируйте: «Я злюсь и мне нужна пауза»; «Мне не подходит такой тон»; «Я продолжу разговор, когда успокоюсь». Не используйте фразы как способ заставить другого терпеть угрозы.'],['Ответственность и исправление',7,'Если человек причинил вред, важно прекратить действие, признать конкретный поступок, выслушать последствия и изменить поведение. Извинение не отменяет необходимости обеспечить безопасность и не обязывает пострадавшего прощать.'],['Итог',3,'Повторите: чувство не делает человека плохим; за поступок отвечает тот, кто его совершил. При угрозе нужно подключить взрослого.']],cards:[['Ситуация 1. Проигрыш','Ученик проиграл в игре, сильно разозлился и хочет бросить предмет.','Какие сигналы гнева можно заметить? Как применить СТОП и обеспечить безопасность?'],['Ситуация 2. Обидные слова','Во время спора ученик начинает кричать и оскорблять другого.','Как остановить вредное поведение? Какая фраза поможет выразить злость без унижения?'],['Ситуация 3. После вреда','Ученик толкнул одноклассника, затем сказал «извини», но продолжил угрожать.','Почему одного извинения недостаточно? Что должно измениться, чтобы стало безопаснее?']],exercise:'Заполните личную нейтральную памятку: мой возможный сигнал гнева; безопасная пауза; фраза без угроз; взрослый, к которому можно обратиться. Не нужно озвучивать ответы всему классу.',teacher:'Не стыдите детей за эмоции и не трактуйте упражнение как диагностику. Не требуйте саморегуляции от ребёнка, находящегося под угрозой. При агрессии сначала прекратите опасное действие, обеспечьте безопасность и действуйте по школьному порядку.',ageNotes:'6–10 лет: карточки эмоций, дыхательная пауза и простая фраза «мне нужна помощь». 11–14 лет: сигналы тела, пауза и границы. 15–18 лет: саморегуляция, ответственность, последствия и восстановительные действия только при безопасных условиях.',quiz:[['Что верно про гнев?',['Злиться запрещено','Эмоция допустима, но она не оправдывает причинение вреда','Если злишься, можно угрожать'],1,'Эмоции естественны; каждый отвечает за свои действия.'],['Что означает буква «П» в алгоритме СТОП?',['Подбери безопасный поступок','Продолжай спор','Публично докажи свою правоту'],0,'После паузы важно выбрать безопасное действие или обратиться за помощью.'],['Достаточно ли извиниться, если угрозы продолжаются?',['Да, слова извинения всё исправляют','Нет, нужно прекратить вред и обеспечить безопасность','Пострадавший обязан простить'],1,'Извинение не заменяет прекращение угроз и изменение поведения и не обязывает другого прощать.']]},
    {id:'respectful-class',title:'Как создать в классе правила уважительного общения',topic:'Безопасная школьная среда',ages:['6–10 лет','11–14 лет','15–18 лет'],goal:'Участники формулируют конкретные правила уважительного общения, связывают их с повседневными действиями и понимают роль взрослых в обеспечении безопасности.',materials:'Карточки правил, листы бумаги, маркеры или доска.',intro:'Безопасный класс — это не место, где все обязаны дружить или всегда соглашаться. Это среда, где можно быть разными, говорить «нет», не терпеть унижения и рассчитывать на реакцию взрослых.',steps:[['Начало и безопасность',5,'Напомни: обсуждаем вымышленные примеры, не называем имён и не проводим голосование о том, кто заслуживает уважения.'],['Что такое уважение',7,'Обсудите наблюдаемые действия: не унижать; слушать; уважать отказ; не распространять личную информацию; не исключать намеренно; обращаться за помощью при угрозе.'],['Семь правил класса',10,'Предложи основу: говорить без унижения; слушать; уважать личные границы и отказ; не оставлять человека один на один с опасностью; соблюдать уважение онлайн; не поддерживать намеренное исключение; звать взрослого при угрозе. Класс может уточнить формулировки, но не отменять базовые права.'],['Проверка на практике',8,'Разберите карточки: неприятная шутка продолжается; спор о проекте; повторяющееся исключение. Для каждого случая назовите правило и конкретное действие взрослого.'],['Кто отвечает за выполнение',7,'Обсудите, как педагог и школа реагируют на нарушение правил, как ученик может обратиться за помощью и что происходит, если проблема продолжается. Контакты называйте только реальные, подтверждённые школой.'],['Итог',3,'Выберите одно правило, которое можно заметить в повседневных действиях, и назовите взрослого или канал помощи.']],cards:[['Ситуация 1. Неприятная шутка','Ученик просит прекратить шутки о своей внешности, но они продолжаются.','Какое правило нарушено? Что может сделать взрослый?'],['Ситуация 2. Разногласие','Два ученика не согласны, как выполнять групповое задание. Они спорят, но не унижают друг друга.','Как договориться, не требуя одинакового мнения?'],['Ситуация 3. Повторяющееся исключение','Одного ученика систематически не берут в команды и публично высмеивают.','Какие меры помогут прекратить вред и обеспечить безопасность? Почему одного голосования класса недостаточно?']],exercise:'Создайте короткий «план безопасного класса»: правило, наблюдаемое действие, к которому оно относится, и шаг взрослого, если правило нарушено.',teacher:'Не проводи голосование о том, кто достоин уважения. Не превращай правила в договор, позволяющий большинству ограничивать права отдельного ученика. Не организуй примирение при продолжающейся травле или неравенстве сил. Сначала безопасность и действия взрослых.',ageNotes:'6–10 лет: 4–5 коротких правил с пиктограммами. 11–14 лет: правила общения в классе и цифровой среде. 15–18 лет: совместная разработка процедур обратной связи и ответственности школы.',quiz:[['Что важно для безопасного класса?',['Все должны дружить и думать одинаково','Уважение границ, отсутствие унижений и доступная помощь','Большинство решает, кого можно исключить'],1,'Безопасность не требует одинаковости или обязательной дружбы; права каждого должны уважаться.'],['Может ли класс голосованием отменить право ученика на уважение?',['Нет','Да, если большинство согласилось','Да, если ученик не популярен'],0,'Базовые права и безопасность не зависят от голосования большинства.'],['Что должен сделать взрослый, если унижение продолжается?',['Сказать ребёнку самому разобраться','Обеспечить безопасность и действовать по школьному порядку','Предложить публичное примирение'],1,'Ответственность за реагирование и защиту лежит на взрослых и школе.']]}

  
    ,{id:'boundaries-consent',title:'Личные границы и согласие',topic:'Личные границы',ages:['6–10 лет','11–14 лет','15–18 лет'],goal:'Участники учатся замечать личные границы — телесные, эмоциональные, предметные и цифровые; понимать добровольность согласия, уважать отказ и обращаться за помощью, если границы нарушают.',materials:'Карточки вымышленных ситуаций, листы с тремя зонами «можно без спроса / сначала спроси / нельзя без разрешения», маркеры.',intro:'У каждого человека есть личные границы. Они могут касаться тела, вещей, пространства, чувств, времени и личной информации. Уважение границ не зависит от дружбы, возраста, популярности или мнения большинства. Согласие должно быть добровольным и конкретным; человек может передумать. Молчание, страх, растерянность и давление не означают согласия.',steps:[['Начало и право выбора',5,'Скажи: мы разбираем только вымышленные примеры. Никто не должен рассказывать личные истории, демонстрировать прикосновения или отвечать на вопрос, который кажется неудобным. Можно спокойно пропустить упражнение.'],['Что может быть личной границей',7,'Обсудите четыре области: тело и пространство; личные вещи; чувства и общение; фотографии, переписки, пароли и другие цифровые данные. Подчеркни: границы у разных людей могут различаться.'],['Просьба, согласие и давление',8,'Объясни разницу между просьбой и требованием. Согласие — свободное «да» на конкретное действие. Его можно отозвать. Если человек молчит, боится, растерян или соглашается под давлением, это не свободное согласие.'],['Сортировка ситуаций',10,'Разложите вымышленные карточки по трём зонам: «можно без спроса», «сначала спроси», «нельзя без разрешения». Не превращайте обсуждение в спор о том, кому «можно терпеть». Если ситуация неоднозначна — безопаснее остановиться и спросить.'],['Фразы и безопасный выход',7,'Потренируйте нейтральные фразы: «Спроси меня сначала»; «Я не хочу»; «Пожалуйста, остановись»; «Не публикуй моё фото»; «Мне нужна помощь взрослого». Не разыгрывайте физические прикосновения.'],['Маршрут помощи и завершение',5,'Если отказ игнорируют, есть угрозы, принуждение или нежелательные прикосновения, нужно обратиться к надёжному взрослому. При непосредственной опасности — отойти в безопасное место и срочно привлечь взрослого. Ребёнок не обязан самостоятельно спорить или останавливать нарушителя.']],cards:[['Ситуация 1. Чужая вещь','Одноклассник без спроса берёт чужой телефон и начинает листать фотографии. Владелец просит вернуть телефон.','Какая граница нарушена? Что нужно сделать? Почему дружба не даёт автоматического разрешения?'],['Ситуация 2. Фото в чате','Ученик хочет отправить в общий чат фотографию одноклассника, сделанную на перемене. Одноклассник против.','Как поступить с фотографией? Что означает уважать отказ?'],['Ситуация 3. Давление группы','Компания требует от подростка сообщить пароль от личного аккаунта и говорит: «Если ты друг, тебе нечего скрывать».','Почему это давление, а не свободное согласие? Как безопасно отказаться и к кому обратиться?'],['Ситуация 4. Нежелательное прикосновение','Во время игры один участник просит другого прекратить прикосновения, но просьбу игнорируют.','Что должно произойти сразу? Как привлечь взрослого, не подвергая себя опасности?']],exercise:'Заполните три колонки на вымышленных примерах: «можно без спроса», «сначала спроси», «нельзя без разрешения». Затем выберите две фразы, которыми можно обозначить границу, и один способ обратиться за поддержкой.',teacher:'Не проси детей демонстрировать прикосновения, обниматься, показывать личные переписки или рассказывать о собственном опыте. Не задавай вопросы, предполагающие раскрытие пережитого насилия. Если ребёнок сообщает о нежелательных прикосновениях, принуждении, угрозах или нарушении безопасности, спокойно выслушай, поблагодари за доверие, не проводи самостоятельное расследование и действуй по утверждённому школьному алгоритму защиты ребёнка. Не обещай абсолютную тайну. Не возлагай на ребёнка обязанность самостоятельно остановить нарушителя.',ageNotes:'Возрастная адаптация раскрыта отдельно для каждой группы ниже.',ageVariants:{'6–10 лет':{focus:'Ребёнок замечает простые границы тела, пространства и вещей; учится просить разрешение и звать взрослого.',activity:'Используй картинки: взять карандаш; обнять без спроса; сесть слишком близко; взять игрушку; показать рисунок без разрешения. Ребёнок раскладывает карточки в зоны «можно», «сначала спроси», «нельзя без разрешения». Не используй реальные прикосновения между детьми.',phrases:'«Можно взять?»; «Нет, я не хочу»; «Остановись, пожалуйста»; «Мне нужна помощь».',facilitator:'Объясняй коротко и конкретно. Не говори, что ребёнок всегда обязан громко сказать «нет»: иногда он может испугаться или растеряться. В таком случае он всё равно имеет право на помощь взрослого.'},'11–14 лет':{focus:'Подросток различает добровольное согласие и давление сверстников, понимает границы в общении, фото, переписках и групповых чатах.',activity:'Разбери кейсы: публикация фото без согласия; требование пароля; настойчивые сообщения после просьбы остановиться; давление «докажи, что ты друг». Попроси определить, где есть выбор, а где давление.',phrases:'«Я не согласен(на)»; «Не пересылай это»; «Мой пароль — личная информация»; «Я прекращаю разговор и обращаюсь за помощью».',facilitator:'Не обесценивай цифровые границы фразами «ничего страшного» или «все так делают». Обсуди, что групповое одобрение не делает нарушение допустимым.'},'15–18 лет':{focus:'Старшеклассники анализируют добровольность, конкретность и отзыв согласия, приватность и ответственность за распространение личной информации.',activity:'В малых группах проанализируйте ситуации с давлением авторитетом, угрозой исключения из компании, публикацией изображений и передачей доступа к аккаунту. Составьте безопасный алгоритм прекращения давления и обращения за поддержкой.',phrases:'«Я не даю согласия на публикацию»; «Я передумал(а), прекрати»; «Не используй мои данные без разрешения»; «Мне нужна помощь ответственного взрослого».',facilitator:'Разграничивай добровольное согласие и уступку под угрозой, шантажом или давлением. Не проси участников делиться личным опытом. Подчеркни, что ответственность за нарушение границ несёт тот, кто его совершает, а не человек, чьи границы нарушили.'}},quiz:[['Что означает согласие?', ['Молчание или отсутствие сопротивления','Свободное и конкретное согласие, которое можно отозвать','Согласие, которое дал кто-то другой'],1,'Согласие должно быть добровольным и относиться к конкретному действию. Человек может передумать.'],['Можно ли публиковать фото одноклассника, если он просит этого не делать?', ['Нет, нужно уважать отказ','Да, если фото смешное','Да, если большинство не против'],0,'Отказ одного человека нельзя отменить голосованием или желанием группы.'],['Что делать, если просьбу остановиться игнорируют?', ['Терпеть, чтобы не портить отношения','Ответить угрозой','Отойти в безопасное место и обратиться к взрослому'],2,'Если границы нарушают или возникает угроза, ребёнок вправе привлечь взрослого.'],['Означает ли молчание согласие?', ['Да, всегда','Нет, молчание, страх или растерянность не означают добровольного согласия','Да, если рядом друзья'],1,'Для согласия важно свободное и ясное волеизъявление без давления.']]}

  ];
  // Полная возрастная адаптация шести основных занятий. Формулировки и упражнения различаются по уровню развития.
  const coreAgeVariants={
    'recognize-bullying':{
      '6–10 лет':{focus:'Научиться замечать, когда спор отличается от повторяющихся обид, и понимать, что даже одна угроза требует помощи взрослого.',activity:'Прочитай три короткие истории: спор о выборе игры; повторяющиеся насмешки компанией; единичная угроза. Разложи карточки в группы «можно попробовать договориться» и «нужно позвать взрослого». Не называй реальные имена.',phrases:'«Мне это неприятно»; «Пожалуйста, остановись»; «Мне нужна помощь взрослого».',facilitator:'Используй короткие истории, картинки и конкретные действия. Не проси детей определять, кто «плохой». При угрозе или насилии сразу объясни, что взрослый должен помочь.'},
      '11–14 лет':{focus:'Различать конфликт, агрессию и травлю по повторяемости, дисбалансу сил и причиняемому вреду; распознавать давление группы и цифровые формы.',activity:'Разбери вымышленные кейсы: спор равных участников; повторяющиеся насмешки группы; единичная угроза в чате. Для каждого укажи факты, возможный риск и взрослого, которому следует сообщить.',phrases:'«Это повторяется, и человеку трудно остановить ситуацию»; «Я не буду это пересылать»; «Нужно подключить взрослого».',facilitator:'Подчеркни, что критерии — ориентиры для оценки взрослыми, а не тест для самостоятельной диагностики одноклассников.'},
      '15–18 лет':{focus:'Анализировать повторяемость, дисбаланс сил, цифровой контекст и риск эскалации; понимать границы самостоятельного вмешательства.',activity:'Составь карту фактов по вымышленному кейсу: действия, частота, влияние статуса/численности/доступа к информации, последствия, признаки срочного риска и маршрут сообщения ответственным взрослым.',phrases:'«Важно зафиксировать конкретные действия, а не ярлыки»; «Есть риск для безопасности — сообщаю ответственному взрослому»; «Не буду устраивать публичное расследование».',facilitator:'Не превращай обсуждение в правовую или психологическую диагностику. Рассматривай школьные процедуры и безопасность, а не поиск виноватого голосованием.'}
    },
    'group-pressure':{
      '6–10 лет':{focus:'Понять, что иногда дети повторяют за компанией, чтобы их приняли, но можно не участвовать в обидных действиях.',activity:'На вымышленных историях выбери, что помогает: смеяться вместе, повторять обидное слово, отойти и позвать взрослого, предложить поддержку.',phrases:'«Я не хочу так делать»; «Давайте не будем обижать»; «Пойдём к взрослому».',facilitator:'Не называй детей трусами и не требуй смелой конфронтации. Разреши безопасный вариант — отойти и позвать взрослого.'},
      '11–14 лет':{focus:'Распознавать влияние популярности, страха исключения, реакций и пересылок; выбирать способы не усиливать травлю.',activity:'Разбери кейс общего чата: участник ставит реакцию, потому что боится стать следующей мишенью. Найди три безопасных действия, не требующих публичного спора с группой.',phrases:'«Я не буду это лайкать или пересылать»; «Это может навредить»; «Давай сообщим взрослому».',facilitator:'Обсуждай групповую динамику без закрепления ролей за конкретными учениками. Не перекладывай на свидетеля обязанность остановить травлю.'},
      '15–18 лет':{focus:'Понимать конформность, социальные санкции, влияние статуса и механизмы цифрового усиления; отделять объяснение поведения от его оправдания.',activity:'В малых группах проанализируйте сценарий группового давления: кто задаёт норму, какие последствия ожидаются за отказ, какие действия уменьшают вред и какой канал помощи доступен.',phrases:'«Понимаю давление группы, но не поддерживаю унижение»; «Не распространяю контент»; «Передам информацию ответственному взрослому».',facilitator:'Не романтизируй героическое противостояние группе. Безопасность и обращение к взрослым важнее демонстративной конфронтации.'}
    },
    'support-classmate':{
      '6–10 лет':{focus:'Научиться показать, что одноклассник не один, и позвать взрослого, не пытаясь самостоятельно остановить опасную ситуацию.',activity:'Выбери подходящую фразу к картинке: «Хочешь, я побуду рядом?»; «Пойдём вместе к учителю»; «Сам виноват». Обсуди, почему некоторые слова могут ранить.',phrases:'«Я рядом»; «Хочешь, пойдём к учителю?»; «Давай позовём взрослого».',facilitator:'Не заставляй детей разыгрывать травлю или рассказывать личное. Поддержка может быть очень простой; взрослый отвечает за безопасность.'},
      '11–14 лет':{focus:'Поддерживать без давления, не обесценивать переживания, не обещать опасную тайну и помогать обратиться к взрослому.',activity:'В парах отработайте два вымышленных диалога: одноклассник расстроен после насмешек; в чате распространяют унизительный контент. Практикуйте вопрос о нужной поддержке и предложение пойти к взрослому.',phrases:'«Хочешь рассказать, что тебе сейчас нужно?»; «Я могу пойти с тобой к педагогу»; «Я не буду пересылать это дальше».',facilitator:'Не требуй от ребёнка добиваться признания или конфронтировать с группой. Если есть непосредственная опасность, взрослого привлекают сразу.'},
      '15–18 лет':{focus:'Выстраивать поддерживающий контакт с уважением к автономии человека и одновременно распознавать ситуации, требующие немедленного вмешательства взрослых.',activity:'Составь короткий алгоритм поддержки: нейтральное наблюдение; открытый вопрос; предложение вариантов; границы конфиденциальности; безопасное сопровождение к ответственному взрослому.',phrases:'«Я не буду решать за тебя, но могу быть рядом»; «Есть ли сейчас непосредственная опасность?»; «Давай найдём взрослого, который сможет помочь».',facilitator:'Разделяй уважение к выбору подростка и обязанность реагировать на угрозу жизни, насилие, шантаж или иной срочный риск по школьному порядку.'}
    },
    'cyberbullying-action':{
      '6–10 лет':{focus:'Понять, что неприятные сообщения и картинки в интернете тоже могут причинять вред; запомнить простое правило — остановить экран и позвать взрослого.',activity:'На карточках выбери безопасные действия: ответить обидой; переслать друзьям; закрыть переписку и показать её доверенному взрослому; сообщить о неприятном сообщении.',phrases:'«Мне неприятно»; «Я не буду это пересылать»; «Помоги мне, пожалуйста».',facilitator:'Не возлагай на младшего ребёнка самостоятельную настройку платформ и сбор доказательств. Взрослый помогает оценить ситуацию и действовать.'},
      '11–14 лет':{focus:'Освоить безопасный порядок действий: не отвечать агрессией, не распространять, сохранить необходимые сведения безопасно, блокировать/жаловаться и сообщить взрослому.',activity:'Разбери вымышленный кейс группового чата. Составь последовательность из пяти шагов и отметь, какие действия должен выполнить взрослый.',phrases:'«Я не буду это пересылать»; «Я сохраню нужную информацию и покажу взрослому»; «Мне нужна помощь с блокировкой и жалобой».',facilitator:'Не проси показывать личные переписки. При шантаже, угрозах, интимных материалах и преследовании — незамедлительно подключить ответственных взрослых; не пересылать интимные материалы.'},
      '15–18 лет':{focus:'Оценивать риски цифрового распространения, приватности и шантажа; понимать, как безопасно сохранять сведения и обращаться за поддержкой.',activity:'Смоделируй маршрут реагирования на вымышленный случай: определить срочность; прекратить распространение; сохранить только необходимые сведения безопасным способом; использовать инструменты платформы; обратиться к ответственному взрослому.',phrases:'«Не распространяйте этот материал»; «Есть угроза/шантаж, я сообщаю ответственному взрослому»; «Мне нужна помощь с безопасным сохранением сведений».',facilitator:'Не предлагай самостоятельно контактировать с шантажистом, платить или пересылать интимные изображения. Действуй по школьному порядку и применимым требованиям.'}
    },
    'anger-regulation':{
      '6–10 лет':{focus:'Научиться узнавать простые сигналы злости, сделать паузу и позвать взрослого, если трудно остановиться.',activity:'Выбери карточку эмоции и закончи фразу: «Когда я злюсь, я могу…». Отрепетируй безопасный шаг: остановиться, отойти, спокойно позвать взрослого.',phrases:'«Я злюсь»; «Мне нужна пауза»; «Помоги мне остановиться».',facilitator:'Не стыди за эмоции и не требуй сложных дыхательных техник. Если есть риск причинения вреда, сначала взрослый обеспечивает безопасность.'},
      '11–14 лет':{focus:'Замечать телесные сигналы гнева, использовать алгоритм СТОП и выбирать действие без угроз, оскорблений и мести.',activity:'Для вымышленных ситуаций заполни схему: сигнал тела → пауза → что я чувствую/чего хочу → безопасная фраза или обращение к взрослому.',phrases:'«Я сейчас злюсь и возьму паузу»; «Не говори со мной так»; «Давай подключим взрослого».',facilitator:'Различай обычный спор и опасную ситуацию. Саморегуляция не заменяет защиты ребёнка от травли, угроз или насилия.'},
      '15–18 лет':{focus:'Разделять эмоцию, импульс и действие; оценивать последствия; брать ответственность за причинённый вред без принуждения пострадавшего к прощению.',activity:'Проанализируй вымышленный эпизод по цепочке «триггер — сигнал — импульс — выбор — последствия». Предложи безопасную альтернативу и шаги прекращения вреда.',phrases:'«Я отвечаю за то, что делаю со своей злостью»; «Я прекращаю разговор, чтобы не причинить вред»; «Нужна помощь взрослого».',facilitator:'Не используй упражнение как диагностику и не требуй саморегуляции от человека под угрозой. Восстановительные действия возможны только после обеспечения безопасности и без принуждения к примирению.'}
    },
    'respectful-class':{
      '6–10 лет':{focus:'Сформулировать несколько простых и понятных правил, которые помогают всем чувствовать себя в классе безопаснее.',activity:'Выбери 4–5 карточек с правилами: не обзываем; слушаем; спрашиваем разрешение; не пересылаем обидные картинки; зовём взрослого, если кому-то страшно.',phrases:'«У нас можно быть разными»; «Стоп, мне неприятно»; «Давай позовём учителя».',facilitator:'Используй короткие правила и пиктограммы. Не устраивай голосование о том, кто достоин уважения; базовые права не зависят от мнения большинства.'},
      '11–14 лет':{focus:'Связать правила уважительного общения с реальными действиями в классе, на перемене и в цифровых каналах.',activity:'Для каждого правила запиши наблюдаемое действие и ответ взрослого, если правило нарушено. Проверь правила на вымышленных кейсах: шутки после просьбы остановиться, исключение из чата, спор о проекте.',phrases:'«Мы можем не соглашаться без унижения»; «Не публикуй чужое фото без разрешения»; «Если ситуация продолжается, обращаемся к взрослому».',facilitator:'Не перекладывай исполнение правил только на детей. У школы должен быть понятный и работающий порядок реагирования.'},
      '15–18 лет':{focus:'Разработать понятные нормы коммуникации и безопасные процедуры обратной связи, сохраняя ответственность школы за защиту прав и достоинства каждого.',activity:'Составь проект классного соглашения: наблюдаемые нормы; способы сообщить о нарушении; ответственные взрослые; порядок проверки, что вред прекратился и не возникло ответного давления.',phrases:'«Правило должно защищать достоинство каждого»; «Большинство не может отменить чьи-то права»; «Проверим, работает ли мера безопасности».',facilitator:'Не заменяй локальные акты школы неформальным соглашением класса. Не проводи публичные разборы и принудительную медиацию при продолжающемся давлении.'}
    }
  };
  lessons.forEach(lesson=>{if(coreAgeVariants[lesson.id])lesson.ageVariants=coreAgeVariants[lesson.id];});
  const $=id=>document.getElementById(id); const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let active=lessons[0]; let age='Все возраста';
  const studentTracks=[
    {id:'safety-respect',title:'Безопасность и уважение',lessonId:'recognize-bullying',direction:'Как распознать травлю и отличить её от конфликта'},
    {id:'boundaries',title:'Личные границы и согласие',lessonId:'boundaries-consent',direction:'Как уважать границы и понимать согласие'},
    {id:'conflict',title:'Конфликт, агрессия и травля',lessonId:'group-pressure',direction:'Почему возникает давление группы и как ему противостоять'},
    {id:'emotions',title:'Эмоции и саморегуляция',lessonId:'anger-regulation',direction:'Как управлять гневом и остановить агрессивное поведение'},
    {id:'witness-support',title:'Свидетель и безопасная поддержка',lessonId:'witness',direction:'Как поддержать одноклассника и не усилить вред'},
    {id:'online-safety',title:'Безопасность в интернете',lessonId:'cyberbullying-action',direction:'Что делать при травле и угрозах в сети'},
    {id:'words-impact',title:'Слова, шутки и последствия',lessonId:'respectful-class',direction:'Как общаться без унижения и давления'},
    {id:'responsibility',title:'Ответственность и восстановление безопасности',lessonId:'safe-climate',direction:'Какие действия помогают вернуть безопасную среду'},
    {id:'help-route',title:'Маршруты помощи',lessonId:'help-route',direction:'Как обратиться к взрослому и быть услышанным'},
    {id:'safe-school',title:'Школа, в которой безопаснее',lessonId:'support-classmate',direction:'Как поддержка и действия взрослых меняют школьную среду'}
  ];
  const studentLessons=studentTracks.map(t=>({...t,lesson:lessons.find(l=>l.id===t.lessonId)})).filter(t=>t.lesson);
  const progressKey='myryadom-student-progress-v2',draftKey='myryadom-student-drafts-v2',stateKey='myryadom-student-route-v2';
  let studentAge='6–10 лет',studentActive=studentLessons[0]||null,studentAnswers={},studentTaskDone=false;
  let studentProgress={},studentDrafts={};
  try{studentProgress=JSON.parse(localStorage.getItem(progressKey)||'{}')||{};}catch(e){studentProgress={};}
  try{const old=JSON.parse(localStorage.getItem('myryadom-student-progress-v1')||'{}')||{};const migrate={'recognize-bullying':'safety-respect','group-pressure':'conflict','support-classmate':'safe-school','cyberbullying-action':'online-safety','anger-regulation':'emotions','respectful-class':'words-impact'};Object.entries(old).forEach(([k,v])=>{const parts=k.split('|');if(parts.length===2&&migrate[parts[1]]){const nk=`${parts[0]}|${migrate[parts[1]]}`;if(!studentProgress[nk])studentProgress[nk]=v;}});localStorage.setItem(progressKey,JSON.stringify(studentProgress));}catch(e){}
  try{studentDrafts=JSON.parse(localStorage.getItem(draftKey)||'{}')||{};}catch(e){studentDrafts={};}
  try{const st=JSON.parse(localStorage.getItem(stateKey)||'{}');if(['6–10 лет','11–14 лет','15–18 лет'].includes(st.age))studentAge=st.age;const found=studentLessons.find(t=>t.id===st.trackId);if(found)studentActive=found;}catch(e){}
  function studentKey(track){return `${studentAge}|${track.id}`;}
  function saveStudentState(){try{localStorage.setItem(draftKey,JSON.stringify(studentDrafts));localStorage.setItem(stateKey,JSON.stringify({age:studentAge,trackId:studentActive?.id||studentLessons[0]?.id}));}catch(e){}}
  function saveStudentDraft(){if(!studentActive)return;studentDrafts[studentKey(studentActive)]={answers:studentAnswers,taskDone:studentTaskDone,updatedAt:new Date().toISOString()};saveStudentState();}
  function restoreStudentDraft(){const d=studentDrafts[studentKey(studentActive)]||{};studentAnswers=d.answers&&typeof d.answers==='object'?{...d.answers}:{};studentTaskDone=!!d.taskDone;}
  function renderStudentCards(){
    const host=$('studentLessonCards');if(!host)return;
    const completed=studentLessons.filter(t=>studentProgress[studentKey(t)]).length;
    $('studentProgressText').textContent=`Пройдено ${completed} из ${studentLessons.length} направлений`;
    $('studentProgressBar').style.width=(studentLessons.length?completed/studentLessons.length*100:0)+'%';
    host.innerHTML=studentLessons.map((t,i)=>`<button type="button" class="student-card ${studentActive&&studentActive.id===t.id?'active':''}" data-student-lesson="${t.id}"><small>НАПРАВЛЕНИЕ ${i+1} ${studentProgress[studentKey(t)]?'✓ ПРОЙДЕНО':''}</small><b>${esc(t.title)}</b><small>${studentProgress[studentKey(t)]?'Можно повторить':'Открыть занятие →'}</small></button>`).join('');
  }
  function renderStudentContent(){
    const host=$('studentLessonContent');if(!host||!studentActive)return;
    const l=studentActive.lesson,v=l.ageVariants?.[studentAge],qs=l.quiz||[];
    const quizHtml=qs.map((q,i)=>{const chosen=studentAnswers[i];const feedback=Number.isInteger(chosen)?`<div class="student-feedback" role="status"><b>${chosen===q[2]?'Верно!':'Попробуй ещё раз.'}</b> ${esc(q[3])}</div>`:'';return `<section class="quiz-question"><b>${i+1}. ${esc(q[0])}</b>${q[1].map((o,j)=>`<button type="button" class="student-quiz-option ${chosen===j&&chosen===q[2]?'correct':''}" data-student-question="${i}" data-student-answer="${j}" aria-pressed="${chosen===j}">${esc(o)}</button>`).join('')}${feedback}</section>`;}).join('');
    const allAnswered=qs.length>0&&qs.every((q,i)=>Number.isInteger(studentAnswers[i]));
    const score=qs.reduce((n,q,i)=>n+(studentAnswers[i]===q[2]?1:0),0);
    const done=!!studentProgress[studentKey(studentActive)];
    const answered=qs.filter((q,i)=>Number.isInteger(studentAnswers[i])).length;
    host.innerHTML=`<span class="kicker">НАПРАВЛЕНИЕ ${studentLessons.findIndex(t=>t.id===studentActive.id)+1} ИЗ 10 · ${esc(studentAge)}</span><h2>${esc(studentActive.title)}</h2><p>${esc(studentActive.direction)}</p><h3>О чём это занятие</h3><p>${esc(l.intro||l.goal)}</p>${v?`<div class="age-variant"><h3>Что важно понять</h3><p>${esc(v.focus)}</p><h3>Попробуй разобраться</h3><p>${esc(v.activity)}</p><h3>Полезные фразы</h3><p>${esc(v.phrases)}</p></div>`:(l.ageNotes?`<div class="age-variant"><b>Подсказка для возраста</b><p>${esc(l.ageNotes)}</p></div>`:'')}<h3>Небольшое задание</h3><label class="student-task"><input type="checkbox" id="studentTaskDone" ${studentTaskDone?'checked':''}> <span>${esc(l.exercise)}<small style="display:block;color:#637887;margin-top:6px">Отметь, когда обдумаешь или выполнишь задание. Личный ответ записывать не нужно.</small></span></label><h3>Проверь себя</h3><p>Выбери ответ. Объяснение появится сразу. Ответ можно изменить.</p>${quizHtml}${allAnswered?`<div class="student-feedback"><b>Результат: ${score} из ${qs.length}</b><p>${score===qs.length?'Отлично! Все ответы верны.':'Проверка завершена. Можно вернуться к вопросам и исправить ответы.'}</p></div>`:`<p class="quiz-progress">Отвечено: ${answered} из ${qs.length}</p>`}<button type="button" class="student-complete" id="studentComplete" ${(!allAnswered||!studentTaskDone)?'disabled':''}>${done?'Направление уже отмечено как пройденное':'Завершить направление'}</button><p class="source-note">Текущий этап, ответы и завершённые направления сохраняются на этом устройстве. Данные не отправляются на сервер. Не вводи имя и личные истории.</p>`;
    const task=$('studentTaskDone');if(task)task.addEventListener('change',()=>{studentTaskDone=task.checked;saveStudentDraft();renderStudentContent();});
    host.querySelectorAll('[data-student-question]').forEach(b=>b.addEventListener('click',()=>{studentAnswers[Number(b.dataset.studentQuestion)]=Number(b.dataset.studentAnswer);saveStudentDraft();renderStudentContent();}));
    const complete=$('studentComplete');if(complete)complete.addEventListener('click',()=>{if(!allAnswered||!studentTaskDone)return;studentProgress[studentKey(studentActive)]={completedAt:new Date().toISOString(),score,total:qs.length};try{localStorage.setItem(progressKey,JSON.stringify(studentProgress));}catch(e){}renderStudentCards();renderStudentContent();});
  }
  function openStudentLesson(id){const t=studentLessons.find(x=>x.id===id);if(!t)return;studentActive=t;restoreStudentDraft();saveStudentState();renderStudentCards();renderStudentContent();if(window.matchMedia('(max-width:760px)').matches)$('studentLessonContent').scrollIntoView({behavior:'smooth',block:'start'});}
  $('showStudent').addEventListener('click',()=>{ $('studentMode').hidden=false;$('teacherMode').hidden=true;$('showStudent').setAttribute('aria-pressed','true');$('showTeacher').setAttribute('aria-pressed','false');restoreStudentDraft();renderStudentCards();renderStudentContent();});
  $('showTeacher').addEventListener('click',()=>{ $('studentMode').hidden=true;$('teacherMode').hidden=false;$('showStudent').setAttribute('aria-pressed','false');$('showTeacher').setAttribute('aria-pressed','true');});
  $('studentAge').value=studentAge;
  $('studentAge').addEventListener('change',e=>{studentAge=e.target.value;restoreStudentDraft();saveStudentState();renderStudentCards();renderStudentContent();});
  $('studentLessonCards').addEventListener('click',e=>{const b=e.target.closest('[data-student-lesson]');if(b)openStudentLesson(b.dataset.studentLesson);});
  function renderList(){
    const q=($('searchLesson').value||'').trim().toLocaleLowerCase('ru');
    const items=lessons.filter(x=>(age==='Все возраста'||x.ages.includes(age))&&(!q||(x.title+' '+x.topic+' '+x.goal+' '+x.materials+' '+x.exercise).toLocaleLowerCase('ru').includes(q)));
    $('lessonCount').textContent=`Найдено тем: ${items.length} из ${lessons.length}`;
    $('lessonCards').innerHTML=items.map(x=>`<button class="lesson-card ${x.id===active.id?'selected':''}" type="button" data-id="${x.id}" aria-pressed="${x.id===active.id}"><span class="kicker">${esc(x.topic)}</span><b>${esc(x.title)}</b><small>${esc(x.ages.join(' · '))}</small></button>`).join('')||'<p class="admin-muted">По этому запросу занятий не найдено. Измени запрос или выбери «Все возраста».</p>';
  }
  let quizAnswers = {};
  function renderQuiz(){
    const host=$('lessonQuiz'); if(!host) return;
    const qs=active.quiz||[];
    if(!qs.length){host.innerHTML='<p class="admin-muted">Проверка знаний для этого материала готовится.</p>';return;}
    const answered=qs.filter((q,i)=>Number.isInteger(quizAnswers[i])).length;
    host.innerHTML=qs.map((q,i)=>{
      const chosen=quizAnswers[i];
      const feedback=Number.isInteger(chosen)?`<p class="quiz-feedback ${chosen===q[2]?'correct':'incorrect'}" role="status">${chosen===q[2]?'Верно.':'Пока неверно.'} ${esc(q[3])}</p>`:'';
      return `<fieldset class="quiz-question"><legend>${i+1}. ${esc(q[0])}</legend><div class="quiz-options">${q[1].map((option,j)=>`<button type="button" class="quiz-option ${chosen===j?'chosen':''} ${Number.isInteger(chosen)&&j===q[2]?'is-correct':''}" data-quiz-question="${i}" data-quiz-answer="${j}" aria-pressed="${chosen===j}">${esc(option)}</button>`).join('')}</div>${feedback}</fieldset>`;
    }).join('');
    if(answered===qs.length){const score=qs.reduce((n,q,i)=>n+(quizAnswers[i]===q[2]?1:0),0);host.innerHTML+=`<div class="quiz-result" role="status"><b>Результат: ${score} из ${qs.length}</b><p>${score===qs.length?'Отлично! Все ответы верны.':'Проверка завершена. Можно вернуться к вопросам и изменить ответы.'}</p></div>`;}
    else host.innerHTML+=`<p class="quiz-progress">Отвечено: ${answered} из ${qs.length}. После каждого ответа появится объяснение.</p>`;
  }
  function renderDetail(){
    const l=active; quizAnswers={};
    $('lessonDetail').innerHTML=`<article class="lesson-print"><span class="kicker">МЫ РЯДОМ · УЧЕБНОЕ ЗАНЯТИЕ</span><h2>${esc(l.title)}</h2><p><b>Возраст:</b> ${esc(age==='Все возраста'?l.ages.join(', '):age)} · <b>Время:</b> 40–45 минут</p><h3>Цель</h3><p>${esc(l.goal)}</p>${l.intro?`<h3>Главная мысль</h3><p>${esc(l.intro)}</p>`:''}<h3>Материалы</h3><p>${esc(l.materials)}</p><h3>Ход занятия</h3><ol>${l.steps.map(s=>`<li><b>${esc(s[0])} — ${s[1]} мин.</b><p>${esc(s[2])}</p></li>`).join('')}</ol><h3>Практическое задание</h3><p>${esc(l.exercise)}</p>${l.ageVariants?`<h3>Возрастная адаптация</h3>${Object.entries(l.ageVariants).filter(([group])=>age==='Все возраста'||age===group).map(([group,v])=>`<div class="age-variant"><h4>${esc(group)}</h4><p><b>Фокус:</b> ${esc(v.focus)}</p><p><b>Упражнение:</b> ${esc(v.activity)}</p><p><b>Фразы:</b> ${esc(v.phrases)}</p><p><b>Ведущему:</b> ${esc(v.facilitator)}</p></div>`).join('')}`:l.ageNotes?`<h3>Возрастная адаптация</h3><p>${esc(l.ageNotes)}</p>`:''}<h3>Рекомендации педагогу</h3><p>${esc(l.teacher)}</p><p class="source-note">Материал — методический шаблон для адаптации. До применения согласовать с педагогом-психологом и ответственным специалистом школы. При реальном сообщении о травле или угрозе действовать по утверждённому школьному порядку.</p></article><section class="lesson-quiz-screen"><h3>Проверка знаний</h3><p>Выбери ответ. Обратная связь появится сразу после каждого выбора. Ответ можно изменить.</p><div id="lessonQuiz"></div></section><h3>Карточки ситуаций для печати</h3><div class="print-cards">${l.cards.map(c=>`<article class="situation-card"><b>${esc(c[0])}</b><p>${esc(c[1])}</p><i>Вопросы:</i><p>${esc(c[2])}</p></article>`).join('')}</div>`;
    renderQuiz();
  }
  $('lessonCards').addEventListener('click',e=>{const b=e.target.closest('button[data-id]');if(!b)return;const chosen=lessons.find(x=>x.id===b.dataset.id);if(!chosen)return;active=chosen;renderList();renderDetail();if(window.matchMedia('(max-width: 760px)').matches)$('lessonDetail').scrollIntoView({behavior:'smooth',block:'start'});});
  $('lessonDetail').addEventListener('click',e=>{const b=e.target.closest('button[data-quiz-question]');if(!b)return;const qi=Number(b.dataset.quizQuestion),ai=Number(b.dataset.quizAnswer);if(!Number.isInteger(qi)||!Number.isInteger(ai))return;quizAnswers[qi]=ai;renderQuiz();});
  $('searchButton').addEventListener('click',renderList);
  $('searchLesson').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();renderList();}});
  $('ageFilter').addEventListener('change',e=>{age=e.target.value;renderList();if(active.ageVariants)renderDetail();});
  $('printLessonPack').addEventListener('click',()=>{ $('printStatus').textContent='Открой системное окно печати. Чтобы получить PDF, выбери «Сохранить как PDF».'; window.print(); });
  renderList();renderDetail();
  if(typeof window!=='undefined'&&window.location&&window.location.search.includes('mode=student'))$('showStudent').click();
})();
